-- =====================================================================
-- Strive Elite - the Recruiting course (templates and rules of thumb)
-- =====================================================================
-- Coach Yinka, Oct 26 2026: "what they need is templates, like how to
-- build a CV, or how to email colleges, templates for before games,
-- after games, follow ups, rules of thumb." A LESSON course: nine pages,
-- no video needed. Seeded SWITCHED OFF; Coach Yinka reads it and flips
-- it on at /coach/drills. Every outcome line stays "a clear path and a
-- player ready for the moment", never a roster or a scholarship (his
-- Oct 5 rule); no recruiting-rule dates are stated anywhere, since
-- those change by year and level and are his to add. Idempotent.
-- Source of the text: the migration itself is the record.
-- =====================================================================

do $$
declare
  cid uuid;
  placed int;
begin
  if exists (select 1 from public.elite_courses where slug = 'recruiting') then
    return;
  end if;
  insert into public.elite_courses (slug, name, subtitle, intro, kind, active, sort)
  values ('recruiting', 'Recruiting', 'Templates and rules of thumb.', E'Copy the template, fill the brackets, send it yourself.\nThe player sends every email. Never the parent.\nKeep it short. Coaches read on their phones between sessions.', 'lesson', false, 50)
  returning id into cid;
  insert into public.elite_course_steps (course_id, level_no, level_name, title, body, sort) values
    (cid, 1, 'The soccer CV', 'The one-page CV', E'One page. If it runs onto a second page, cut it. A coach gives it thirty seconds.\n\nTEMPLATE\n\n[Full name]\n[Graduation year] | [Position, then second position] | [Preferred foot]\n[Height] | [Date of birth]\n[City, State] | [Email the player checks] | [Phone]\nTape: [link] | Full games: [link]\n\nCLUB\n[Club name], [team and league, e.g. U15 MLS NEXT], [years], [role: starter, captain]\n[Previous club], [team and league], [years]\n\nSCHOOL\n[High school], [GPA], [graduation year], [SAT or ACT if taken]\n[Honors, AP classes, anything academic a coach can use]\n\nHONORS\n[Only real, dated ones: All-Conference 2026, ODP pool 2025, team captain 2026]\n\nCOACH REFERENCES\n[Club coach name], [club], [phone], [email]\n[Second coach or trainer], [phone], [email]\n\nRULES OF THUMB\n\nFacts only. No adjectives about yourself. "Hard worker" means nothing on paper; a GPA and a league do.\n\nPut the tape link at the top. It is the only line most coaches click.\n\nUpdate it every season. A CV from last year reads like you stopped caring.\n\nSave it as a PDF named [Last name]-[First name]-[Grad year].pdf. Never a Word file, never a photo of a page.\n\nAsk your coach references before you list them. Every time.', 10),
    (cid, 2, 'Emails', 'The first email to a coach', E'Send this before anything else. One coach, one email, written by the player. Never a mass email, never from a parent''s address.\n\nSUBJECT: [Grad year] [Position] | [Club, league] | [Your name]\n\nTEMPLATE\n\nCoach [Last name],\n\nMy name is [First Last], a [grad year] [position] with [club] in [league]. I am writing because I want to play at [school or club] and I have been following [one true specific thing: how the team plays, a recent result, a player who came from a club like mine].\n\nHere is my tape: [link]\nFull game: [link]\nCV attached.\n\nI will be at [event] on [date], field [number], kickoff [time], wearing [number], if you are able to watch. If not, I would be grateful for any feedback on the tape.\n\nThank you for your time.\n\n[First Last]\n[Grad year], [Position]\n[Phone]\n[Club coach name], [phone] (reference)\n\nRULES OF THUMB\n\nOne specific true line about their program. That is the whole difference between an email that gets opened and one that gets deleted.\n\nUnder 150 words. Everything a coach needs is in the links and the attachment.\n\nSend it from an email address that is your name, not a nickname.\n\nSend it on a weekday morning. Not Friday afternoon, not game day.', 10),
    (cid, 2, 'Emails', 'Before a game or showcase', E'Send this five to seven days before the event, and again the morning of, two lines only.\n\nSUBJECT: [Event], [date] | [Your name], [grad year] [position]\n\nTEMPLATE, A WEEK OUT\n\nCoach [Last name],\n\nI wanted to let you know I will be playing at [event] on [date].\n\n[Team] vs [opponent]\n[Day, date], kickoff [time]\n[Venue], field [number]\nJersey number [number], [position]\n\nMy tape is here if useful before the game: [link]\n\nI would love for you to watch. Thank you.\n\n[First Last]\n[Phone]\n\nTEMPLATE, THE MORNING OF\n\nCoach [Last name], playing today at [time] on field [number], number [number]. Hope to see you there. [First Last]\n\nRULES OF THUMB\n\nGive them everything they need to find you in ten seconds: field, time, number. Coaches walk between six fields.\n\nNever ask if they are coming. Tell them where you will be.\n\nIf the schedule changes, send one more line. A coach who walks to the wrong field does not come back.', 20),
    (cid, 2, 'Emails', 'After a game they watched', E'Send this within 24 hours. Even if you played badly. Especially if you played badly.\n\nSUBJECT: Thank you for watching, [event]\n\nTEMPLATE\n\nCoach [Last name],\n\nThank you for coming to watch [team] vs [opponent] on [date].\n\n[One honest line about the game: what went well, or what you know you need to fix. Never an excuse.]\n\nI am very interested in [school or club]. If you have any feedback, or if there is a next step you would like me to take, I would be grateful to hear it.\n\n[Updated tape link, if you have new clips from that game]\n\nThank you again for your time.\n\n[First Last]\n[Phone]\n\nRULES OF THUMB\n\nNever blame the referee, the pitch, a teammate or the coach. A coach who reads an excuse stops reading.\n\nOne honest line about your own game shows more maturity than any highlight.\n\nIf they gave you feedback at the field, repeat it back: "You mentioned my first touch under pressure. I am working on it." Coaches remember who listened.', 30),
    (cid, 2, 'Emails', 'The follow-up when nobody replies', E'Most coaches do not reply to the first email. That is normal. Send this two weeks after the last one.\n\nSUBJECT: Following up | [Your name], [grad year] [position]\n\nTEMPLATE\n\nCoach [Last name],\n\nI wanted to follow up on my email from [date]. I remain very interested in [school or club].\n\nSince then: [one new thing, true: a new tape, a result, a grade, an event you will be at].\n\nTape: [link]\n\nThank you for your time.\n\n[First Last]\n[Phone]\n\nRULES OF THUMB\n\nAlways bring something new. "Just checking in" with nothing new gets deleted.\n\nTwo follow-ups, two weeks apart. After that, leave it until you have a real update or a new event near them.\n\nNo reply is not a no. Coaches are not allowed to reply to younger players at some levels, and they still read. Keep the emails coming at each real update.', 40),
    (cid, 2, 'Emails', 'After an ID camp or a visit', E'Send this the same evening or the next morning.\n\nSUBJECT: Thank you, [camp or visit], [date]\n\nTEMPLATE\n\nCoach [Last name],\n\nThank you for [the camp, the visit, the time you gave me] on [date].\n\n[One specific thing you took from it: a drill, something they said, something about the program you saw.]\n\n[If true: After seeing it in person, [school or club] is where I want to play.]\n\nMy tape: [link]\n\nI will keep you updated as the season goes. Thank you again.\n\n[First Last]\n[Grad year], [Position]\n[Phone]\n\nRULES OF THUMB\n\nName the specific thing. "Great camp" says nothing. "The possession game in the second session showed me how you want center backs to play" says you were paying attention.\n\nSay you want it only if you mean it. Coaches compare notes.', 50),
    (cid, 3, 'The tape', 'Highlight tape rules of thumb', E'Three to four minutes. Your best five clips in the first forty seconds. Coaches decide whether to keep watching before the first minute ends.\n\nWHAT GOES IN\n\nYour position''s job, over and over. A striker''s tape is goals and the runs before them. A center back''s tape is duels, headers, first passes out. A midfielder''s tape is receiving under pressure and what happens next.\n\nEvery clip starts a few seconds before your touch so the coach sees the picture you saw.\n\nMark yourself at the start of every clip: a circle or an arrow for the first second, then gone.\n\nWHAT STAYS OUT\n\nMusic. Most coaches watch on mute, and the ones who do not want to hear the game.\n\nSlow motion, effects, titles between clips. One title card at the start with your name, grad year, position, club, email. Nothing else.\n\nClips from training. Game footage only. A trick against a cone proves nothing.\n\nAnything longer than four minutes. A coach who wants more will ask for the full game.\n\nTHE FULL GAME\n\nAlways have one full match available as a link. Unedited. Put the link under the tape link in every email. The tape gets the door open; the full game gets you through it.\n\nHOSTING\n\nUnlisted on a video site, link in the CV and every email. Check the link works from a phone that is not yours before you send it.\n\nUpdate the tape every season. Put the newest clips first. Date it in the title: [Name] [Position] [Grad year] | Fall 2026.', 10),
    (cid, 4, 'Rules of thumb', 'The rules nobody tells you', E'THE PLAYER DOES THE WORK\n\nThe player writes every email. The player answers the phone. A coach who hears from a parent first assumes the player does not want it enough.\n\nParents: proofread, drive, pay for the tape. That is the job.\n\nTHE LIST\n\nMake a list of twenty programs across three levels: five that would be a stretch, ten that fit, five that would say yes today. Email all twenty. The ones that reply are your list now.\n\nNever only the dream schools. Never only the safe ones.\n\nTIMING\n\nEmail a coach when you have something: a new tape, an event near them, a result, a grade. Not on a schedule, not when you are bored.\n\nA week before an event, then the morning of. Within a day after. Two weeks later if silence. Then only with news.\n\nWHAT COACHES ACTUALLY CHECK\n\nYour tape, then your full game, then your grades, then they call your club coach. Make sure all four are ready before the first email goes out. One weak link and the process stops there.\n\nYour club coach''s phone number is on your CV. Tell your club coach it is there and what you are aiming for.\n\nSOCIAL MEDIA\n\nAssume every coach reads your accounts before they reply. Clean it up before the first email, not after.\n\nTHE TRACKER\n\nKeep one sheet. Every program, every email, every date, every reply. The next step is always written down. See the next page.\n\nWHAT WE NEVER PROMISE\n\nNobody can promise a roster spot or a scholarship, not us, not anyone. What the work promises is a clear path and a player ready for the moment. That is the whole job.', 10),
    (cid, 4, 'Rules of thumb', 'The tracker', E'One row per program. Update it the day anything happens. If it is not on the sheet, it did not happen.\n\nCOLUMNS\n\nProgram | Level (stretch, fit, yes) | Coach name | Coach email | First email sent | Replied (date) | Last contact | Next step | Next step date | Notes\n\nRULES OF THUMB\n\nNext step is never blank. Even "follow up Nov 12" or "send fall tape when done" counts.\n\nRead the sheet every Sunday. Five minutes. Do whatever is due that week.\n\nTwenty rows. When one goes cold, add one. When one says yes, keep the others warm until you have decided.\n\nThe sheet belongs to the player. The parent can see it. The player keeps it.', 20);
  select count(*) into placed from public.elite_course_steps where course_id = cid;
  if placed <> 9 then
    raise exception 'Recruiting seed placed % of 9 pages', placed;
  end if;
end $$;
